from pathlib import Path
import re

ROOT=Path(__file__).resolve().parents[1]
path=ROOT/'schedule-center-v1.html'
text=path.read_text(encoding='utf-8')
SCRIPT=r'''<script>
(()=>{'use strict';const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#039;'}[c]));let st={view:'day',date:new Date(),doctor:'',search:'',bookings:[],doctors:[]};const key=d=>new Date(d).toISOString().slice(0,10);const tr=(a,e)=>String(document.documentElement.lang||'ar').toLowerCase().startsWith('en')?e:a;async function api(url){const r=await fetch(url,{credentials:'include',cache:'no-store',headers:{Accept:'application/json'}});const b=await r.json().catch(()=>({}));if(!r.ok)throw Error(b.error||b.message||`HTTP ${r.status}`);return b}async function load(){try{$('root').innerHTML='<div class="loading">⏳ جاري التحميل...</div>';const auth=await api('/api/admin-auth');if(!['OWNER','ADMIN','MANAGER','SECRETARY','RECEPTION','DOCTOR'].includes(String(auth.staff?.role||'').toUpperCase()))throw Error('ليس لديك صلاحية الجدولة.');const d=key(st.date),to=st.view==='week'?key(new Date(st.date.getTime()+6*86400000)):st.view==='month'?key(new Date(st.date.getFullYear(),st.date.getMonth()+1,0)):d;const b=await api(`/api/admin-appointments?from=${encodeURIComponent(d)}&to=${encodeURIComponent(to)}&limit=500`);st.bookings=b.appointments||[];st.doctors=[...new Map(st.bookings.map(x=>[x.doctor_id,{id:x.doctor_id,name:x.doctor_name||x.doctor?.name||x.doctor_name_en||'طبيب'}]).filter(x=>x[0])).values()];$('doctor').innerHTML='<option value="">🧑‍⚕️ كل الأطباء</option>'+st.doctors.map(x=>`<option value="${esc(x.id)}">${esc(x.name)}</option>`).join('');$('doctor').value=st.doctor;render()}catch(e){$('root').innerHTML=`<div class="error">⚠️ ${esc(e.message)}</div>`}}function status(v){v=String(v||'').toLowerCase();if(['booked','scheduled','confirmed'].includes(v))return['confirmed','🔵','مؤكد'];if(['pending_confirmation','awaiting_confirmation'].includes(v))return['pending','🟡','انتظار تأكيد'];if(['no-show','noshow'].includes(v))return['no_show','🟠','No-show'];if(['cancelled','canceled'].includes(v))return['cancelled','🔴','ملغي'];if(['closed','holiday','blocked'].includes(v))return['closed','⚫','مغلق'];return['available','🟢','متاح']}function rows(){const q=st.search.toLowerCase().trim();return st.bookings.filter(r=>{if(st.view==='day'&&String(r.appointment_date)!==key(st.date))return false;if(st.doctor&&String(r.doctor_id)!==String(st.doctor))return false;return!q||`${r.patient_name||r.patient?.patient_name||''} ${r.mrn||r.patient?.mrn||''} ${r.patient_phone||r.patient?.patient_phone||''} ${r.booking_code||''}`.toLowerCase().includes(q)})}function dayList(d,docs,rs){const dk=key(d);return`<div style="margin-bottom:18px"><div class="head"><h2>📅 ${esc(d.toLocaleDateString('ar-EG',{weekday:'long',year:'numeric',month:'long',day:'numeric'}))}</h2><span class="muted">${rs.filter(r=>String(r.appointment_date)===dk).length} حجز</span></div><div class="calendar"><div class="grid">${docs.map(doc=>{const rr=rs.filter(r=>String(r.appointment_date)===dk&&String(r.doctor_id)===String(doc.id));return`<div class="doctor-row"><div class="doctor"><strong>🧑‍⚕️ ${esc(doc.name)}</strong></div><div class="timeline">${Array.from({length:24},(_,h)=>`<div class="hour">${h===0?12:h>12?h-12:h}:00</div>`).join('')}<div class="slots">${rr.length?rr.map(r=>{const[c,i,l]=status(r.status);return`<div class="slot ${c}"><strong>${esc(String(r.appointment_time||'').slice(0,5)||'—')} ${i} ${l}</strong><span>${esc(r.patient_name||r.patient?.patient_name||'مريض')}</span><small>${esc(r.mrn||r.patient?.mrn||r.booking_code||'')}</small></div>`}).join(''):'<span class="muted">لا توجد حجوزات لهذا الطبيب في هذا اليوم.</span>'}</div></div></div>`}).join('')}</div></div></div>`}function render(){const rs=rows(),docs=st.doctors.filter(d=>!st.doctor||String(d.id)===String(st.doctor));if(!docs.length){$('root').innerHTML='<div class="empty">لا توجد بيانات أطباء ضمن الصلاحية الحالية.</div>';return}if(st.view==='week'){const start=new Date(st.date);const day=start.getDay();start.setDate(start.getDate()-(day===0?6:day-1));$('root').innerHTML=Array.from({length:7},(_,i)=>{const d=new Date(start);d.setDate(start.getDate()+i);return dayList(d,docs,rs)}).join('');return}if(st.view==='month'){const groups={};rs.forEach(r=>(groups[r.appointment_date]??=[]).push(r));const ds=Object.keys(groups).sort();$('root').innerHTML=ds.length?ds.map(d=>dayList(new Date(d+'T00:00:00'),docs,groups[d])).join(''):'<div class="empty">لا توجد حجوزات في الشهر المحدد.</div>';return}$('root').innerHTML=dayList(st.date,docs,rs)}function move(n){const d=new Date(st.date);if(st.view==='day')d.setDate(d.getDate()+n);else if(st.view==='week')d.setDate(d.getDate()+7*n);else d.setMonth(d.getMonth()+n);st.date=d;$('date').value=key(d);load()}$('date').value=key(st.date);$('refresh').onclick=load;$('prev').onclick=()=>move(-1);$('next').onclick=()=>move(1);$('back').onclick=()=>location.href='./admin.html';$('doctor').onchange=e=>{st.doctor=e.target.value;render()};$('search').oninput=e=>{st.search=e.target.value;render()};$('date').onchange=e=>{st.date=new Date(e.target.value+'T00:00:00');load()};document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{st.view=b.dataset.view;document.querySelectorAll('[data-view]').forEach(x=>x.classList.toggle('active',x===b));load()});load()})();
</script>'''
new,n=re.subn(r'<script\s+type=["\']module["\'][^>]*>[\s\S]*?</script>',SCRIPT,text,count=1,flags=re.I)
if n!=1:raise SystemExit(f'FAIL-CLOSED: expected exactly one legacy schedule runtime module, found {n}')
if 'supabase.co' in new.lower() or 'createClient(' in new or 'functions/v1/' in new:raise SystemExit('FAIL-CLOSED: legacy Supabase schedule runtime remains')
path.write_text(new,encoding='utf-8')
print('[AZAAD schedule center] PASS: Appwrite-authenticated Neon scheduling runtime written')
